From 7e215242ae91711823de1a921e2aa55ed2207b60 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:37:39 +0100
Subject: [PATCH] shellcontainmentconfiguration: add Clone Panel actions to
 panel menus

The panel menus in Manage Panels and Desktops could move or remove a
panel but not clone it like the panel's own edit mode can. Add "Clone
Panel" and "Clone to Screen" entries for every connected screen.

BUG: 518750
---
 .../Delegate.qml                              | 29 ++++++++++++++++++-
 1 file changed, 28 insertions(+), 1 deletion(-)

diff --git a/desktoppackage/contents/configuration/shellcontainmentconfiguration/Delegate.qml b/desktoppackage/contents/configuration/shellcontainmentconfiguration/Delegate.qml
index 9da4bf0b40..e9d34db4fa 100644
--- a/desktoppackage/contents/configuration/shellcontainmentconfiguration/Delegate.qml
+++ b/desktoppackage/contents/configuration/shellcontainmentconfiguration/Delegate.qml
@@ -17,6 +17,7 @@ QQC2.Control {
     property Item viewPort
     readonly property string screenName: model.screenName
     readonly property int screenId: model.screenId
+    readonly property bool screenEnabled: model.isEnabled
     property bool containsDrag
     property alias contentsLayout: contentsLayout

@@ -54,6 +55,7 @@ QQC2.Control {
                     property real homeX
                     property real homeY
                     property string oldState
+                    readonly property bool canClone: state !== "floating" && delegate.screenEnabled
                     readonly property int edgeDistance: {
                         return (state === "left" || state === "right" ? width : height) * model.edgePosition;
                     }
@@ -194,7 +196,32 @@ QQC2.Control {
                                 }
                             }
                             QQC2.MenuSeparator {
-                                visible: removeItem.visible && contextMenuRepeater.anyActionAvailable
+                                visible: contRect.canClone && contextMenuRepeater.anyActionAvailable
+                            }
+                            QQC2.MenuItem {
+                                text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:inmenu", "Clone Panel")
+                                icon.name: "edit-copy-symbolic"
+                                visible: contRect.canClone
+                                height: visible ? implicitHeight : 0
+                                onTriggered: {
+                                    containmentRepeater.model.clonePanelToScreen(model.containmentId, delegate.screenId)
+                                }
+                            }
+                            Repeater {
+                                model: contRect.canClone ? ShellContainmentModel : null
+
+                                QQC2.MenuItem {
+                                    text: i18ndc("plasma_shell_org.kde.plasma.desktop", "@action:inmenu", "Clone to Screen %1", model.screenName)
+                                    icon.name: "edit-copy-symbolic"
+                                    visible: model.isEnabled && model.screenName !== delegate.screenName
+                                    height: visible ? implicitHeight : 0
+                                    onTriggered: {
+                                        containmentRepeater.model.clonePanelToScreen(containmentId, model.screenId)
+                                    }
+                                }
+                            }
+                            QQC2.MenuSeparator {
+                                visible: removeItem.visible && (contextMenuRepeater.anyActionAvailable || contRect.canClone)
                             }
                             QQC2.MenuItem {
                                 id: removeItem
-- 
