From 23bdedc8a87e3609ca5834623dc7200a58fecd2e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:37:39 +0100
Subject: [PATCH] shell: let Manage Panels and Desktops clone a panel to a
 screen

Panels could only be cloned from their own edit mode toolbar, so the
Manage Panels and Desktops window had no way to do it. Add a method that
clones a panel onto a screen, keeping its edge when that one is free.

BUG: 518750
---
 shell/shellcontainmentconfig.cpp | 29 +++++++++++++++++++++++++++++
 shell/shellcontainmentconfig.h   |  1 +
 2 files changed, 30 insertions(+)

diff --git a/shell/shellcontainmentconfig.cpp b/shell/shellcontainmentconfig.cpp
index 5bc79a9128..7727bcfcc7 100644
--- a/shell/shellcontainmentconfig.cpp
+++ b/shell/shellcontainmentconfig.cpp
@@ -17,6 +17,7 @@
 #include <QQuickItem>
 #include <QScreen>

+#include "panelview.h"
 #include "screenpool.h"
 #include "shellcorona.h"
 #include <algorithm>
@@ -321,6 +322,34 @@ void ShellContainmentModel::moveContainementToScreen(unsigned int contId, int ne
     }
 }

+void ShellContainmentModel::clonePanelToScreen(unsigned int contId, int newScreen)
+{
+    auto *cont = containmentById(contId);
+    if (!cont) {
+        return;
+    }
+    PanelView *panelView = m_corona->panelView(cont);
+    QScreen *screen = m_corona->screenPool()->screenForId(newScreen);
+    if (!panelView || !screen) {
+        return;
+    }
+
+    // Prefer the same edge, otherwise the first edge without a panel on that screen
+    QList<Plasma::Types::Location> availableLocations{cont->location(),
+                                                      Plasma::Types::BottomEdge,
+                                                      Plasma::Types::TopEdge,
+                                                      Plasma::Types::LeftEdge,
+                                                      Plasma::Types::RightEdge};
+    for (const auto *other : m_corona->containments()) {
+        if (!other->destroyed() && other->screen() == newScreen
+            && (other->containmentType() == Plasma::Containment::Panel || other->containmentType() == Plasma::Containment::CustomPanel)) {
+            availableLocations.removeAll(other->location());
+        }
+    }
+
+    m_corona->clonePanelTo(panelView, availableLocations.value(0, cont->location()), screen);
+}
+
 bool ShellContainmentModel::findContainment(unsigned int containmentId) const
 {
     return m_containments.cend() != std::ranges::find_if(m_containments, [containmentId](const Data &d) {
diff --git a/shell/shellcontainmentconfig.h b/shell/shellcontainmentconfig.h
index 5a5378aec5..0c0fb3b2b8 100644
--- a/shell/shellcontainmentconfig.h
+++ b/shell/shellcontainmentconfig.h
@@ -96,6 +96,7 @@ public:

     Q_INVOKABLE void remove(int contId);
     Q_INVOKABLE void moveContainementToScreen(unsigned int contId, int newScreen);
+    Q_INVOKABLE void clonePanelToScreen(unsigned int contId, int newScreen);

     bool findContainment(unsigned int containmentId) const;

